/// <reference types="@sveltejs/kit" />
/// <reference no-default-lib="true"/>
/// <reference lib="esnext" />
/// <reference lib="webworker" />

declare const self: ServiceWorkerGlobalScope;

import { build, files, version } from '$service-worker';

// This is a basic service worker that caches the static assets generated by SvelteKit's build process
const CACHE_NAME = `axon-${version}`;
const ASSETS = [...build, ...files];

self.addEventListener('install', (event) => {
	event.waitUntil(
		caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS)).then(() => self.skipWaiting())
	);
});

self.addEventListener('activate', (event) => {
	// Drop every Axon cache (not only old versions). Stale HTML 500 pages used to
	// stick around and poison full reloads while client-side nav still worked.
	event.waitUntil(
		caches
			.keys()
			.then((keys) => Promise.all(keys.map((k) => caches.delete(k))))
			.then(() => caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS)))
			.then(() => self.clients.claim())
	);
});

// --- Web Push ---------------------------------------------------------------
// Payload is JSON sent by the server (see src/lib/server/push-sender.ts):
// { title, body, url }. `tag` collapses repeat pushes into a single notification
// so an active ingest cadence can't stack a wall of alerts.
self.addEventListener('push', (event) => {
	let data: { title?: string; body?: string; url?: string } = {};
	try {
		data = event.data?.json() ?? {};
	} catch {
		data = { body: event.data?.text() };
	}

	const title = data.title || 'Axon';
	event.waitUntil(
		self.registration.showNotification(title, {
			body: data.body || 'New signals are in.',
			icon: '/icon-192.png',
			badge: '/icon-192.png',
			tag: 'axon-signals',
			renotify: true,
			data: { url: data.url || '/app' }
		} as NotificationOptions)
	);
});

self.addEventListener('notificationclick', (event) => {
	event.notification.close();
	const target = (event.notification.data?.url as string) || '/app';
	event.waitUntil(
		self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clients) => {
			// Focus an existing Axon window if one is open; otherwise open a new one.
			for (const client of clients) {
				if ('focus' in client) {
					const url = new URL(client.url);
					if (url.pathname.startsWith('/app') || url.origin === self.location.origin) {
						client.focus();
						if ('navigate' in client && url.pathname !== target) {
							(client as WindowClient).navigate(target).catch(() => {});
						}
						return;
					}
				}
			}
			return self.clients.openWindow(target);
		})
	);
});

self.addEventListener('fetch', (event) => {
	if (event.request.method !== 'GET') return;

	const url = new URL(event.request.url);
	if (url.origin !== self.location.origin) return;

	// Never intercept navigations or SvelteKit data requests. Caching `/app` HTML
	// (including 500 error pages) made post-login full loads keep showing a stale
	// Internal Error while client-side "Back to feed" still worked via __data.json.
	if (event.request.mode === 'navigate' || url.pathname.includes('__data.json')) {
		return;
	}

	// Never let the service worker touch API calls (feed proxy + auth).
	if (url.pathname.startsWith('/api/')) {
		return;
	}

	// Only cache hashed build assets + static files from the precache list.
	if (ASSETS.includes(url.pathname)) {
		event.respondWith(
			caches.match(event.request).then((cached) => cached || fetch(event.request))
		);
	}
});
